function browserNarration(event){if(event.includes(' | draw'))return event.split(' | ')[0]+' drew a card.';if(event.includes(' | play:'))return event.split(' | ')[0]+' plays '+name(event.split('play:')[1])+'.';if(event.startsWith('system | battle_end:')){const [,outcome,reason]=event.split(':');return outcome==='draw'?'The battle ended in a draw ('+reason+').':outcome+' wins ('+reason+').'}return state.pool.reduce((text,current)=>text.replaceAll(current.card_id,current.display_name),event)}
$('submit').onclick=()=>{try{if(deckSize()<state.config.minimum_deck_size||deckSize()>state.config.maximum_deck_size){$('status').textContent=deckMessage();return}state.running=true;state.session='browser';state.match=null;state.logNumber=null;state.browserSubmission=currentDeckPayload();$('match-panel').hidden=true;$('results-empty').hidden=false;$('results-table-wrap').hidden=true;$('simulation-progress').hidden=false;$('simulation-progress').value=0;setView('results');updateNavigation();$('status').textContent='Starting browser simulations in a background worker…';worker().postMessage({type:'simulate',opponents:state.publicOpponents,submission:state.browserSubmission,games:+$('games').value,actionLimit:+$('action-limit').value})}catch(error){state.running=false;$('status').textContent=error.message;setView('program')}};
function browserMatch(opponent){const match=state.browserMatches.find(item=>item.opponent===opponent);if(!match)return;state.match=opponent;state.browserMatch=match;state.battlePage=0;$('results-table-wrap').hidden=true;$('match-panel').hidden=false;$('match-title').textContent=state.browserSubmission.owner_name+' vs. '+match.opponent_deck.owner_name;renderBrowserBattlePage();$('status').textContent='';setView('results')}
function renderBrowserBattlePage(){const match=state.browserMatch,start=state.battlePage*10,records=match.battles.slice(start,start+10),pages=Math.ceil(match.battles.length/10),end=Math.min(start+records.length,match.battles.length);$('battles').innerHTML=records.map(b=>'<tr tabindex="0" data-browser-battle="'+b.game_number+'"><td>'+b.game_number+'</td><td>'+esc(b.winner_id===null?'Draw':b.winner_id==='first'?'Win':'Loss')+'</td><td>'+b.first_victory_points+'-'+b.second_victory_points+'</td><td>'+esc(b.end_reason)+'</td></tr>').join('');$('battle-pages').innerHTML='<span class="page-label">Battles '+(start+1)+'–'+end+' of '+match.battles.length+'</span><button data-browser-page-step="-1" '+(state.battlePage===0?'disabled':'')+'>← Previous</button><button data-browser-page-step="1" '+(state.battlePage+1===pages?'disabled':'')+'>Next →</button>'}
document.addEventListener('click',event=>{const opponent=event.target.closest('[data-browser-opponent]');if(opponent){event.stopImmediatePropagation();browserMatch(opponent.dataset.browserOpponent);return}const pageStep=event.target.closest('[data-browser-page-step]');if(pageStep){event.stopImmediatePropagation();state.battlePage+=+pageStep.dataset.browserPageStep;renderBrowserBattlePage();return}const battle=event.target.closest('[data-browser-battle]');if(battle){event.stopImmediatePropagation();const record=state.browserMatch.battles.find(item=>item.game_number===+battle.dataset.browserBattle);if(record){state.logNumber=record.game_number;worker().postMessage({type:'replay',submission:state.browserSubmission,opponent:state.browserMatch.opponent_deck,seed:record.seed,gameNumber:record.game_number,actionLimit:+$('action-limit').value})}return}},true);

function playerLabel(id){return id==='first'?state.browserSubmission.owner_name:state.browserMatch.opponent_deck.owner_name}
function readableBattleEvent(event){if(event.endsWith(' | turn_start'))return playerLabel(event.split(' | ')[0])+' begins their turn.';if(event.includes(' | draw'))return playerLabel(event.split(' | ')[0])+' drew a card.';if(event.includes(' | play:'))return playerLabel(event.split(' | ')[0])+' played '+name(event.split('play:')[1])+'.';if(event.includes(' | sync:'))return playerLabel(event.split(' | ')[0])+' now has '+event.split(':').at(-1)+' Sync.';if(event.endsWith(' | end_turn_effect'))return playerLabel(event.split(' | ')[0])+' ended their turn from a card effect.';if(event.endsWith(' | end_turn_action'))return playerLabel(event.split(' | ')[0])+' ended their turn.';if(event.startsWith('system | battle_end:')){const [,winner,reason]=event.split(':');const ending={flux:'by reaching the Flux goal',sync:'by reducing their opponent’s Sync to 0',deck_exhausted:'when their opponent could not draw from their deck',action_limit:'when the action limit was reached',action_limit_tie:'when the action limit was reached'}[reason]||'('+reason+')';return winner==='draw'?'The battle ended in a draw '+ending+'.':playerLabel(winner)+' won '+ending+'.'}return ''}
function battleTurns(events){const turns=[];let current;for(const event of events){if(event.endsWith(' | turn_start')){current=[];turns.push(current)}const line=readableBattleEvent(event);if(line){if(!current){current=[];turns.push(current)}current.push(line)}}return turns.filter(turn=>turn.length)}
function legacyRenderBrowserLog(battle){state.logTurns=battleTurns(battle.log);state.logTurnIndex=0;state.logMode='full';$('log-title').textContent='Battle '+battle.game_number;legacyRenderLogDisplay()}
function legacyRenderLogDisplay(){const turns=state.logTurns||[];const viewingTurns=state.logMode==='turns';const visible=viewingTurns?(turns[state.logTurnIndex]||[]):turns.flat();$('log').textContent=visible.join('\n');if(!viewingTurns){$('log-controls').innerHTML='<button data-log-mode="turns">View Turns</button>';return}const first=state.logTurnIndex===0,last=state.logTurnIndex===turns.length-1;$('log-controls').innerHTML='<button data-log-mode="full">Show Full Log</button><span class="log-turn-label">Turn '+(state.logTurnIndex+1)+' of '+turns.length+'</span><button data-log-turn="-1" '+(first?'disabled':'')+'>← Prev Turn</button><button class="next-turn" data-log-turn="1" '+(last?'disabled':'')+'>Next Turn →</button>'}
document.addEventListener('click',event=>{const mode=event.target.closest('[data-log-mode]');if(mode){state.logMode=mode.dataset.logMode;state.logTurnIndex=0;renderLogDisplay();return}const turn=event.target.closest('[data-log-turn]');if(turn){state.logTurnIndex=Math.max(0,Math.min((state.logTurns||[]).length-1,state.logTurnIndex+Number(turn.dataset.logTurn)));renderLogDisplay()}},true);

/* Default-action policy and random-card eligibility. */
state.defaultAction='play_random_card';state.randomEligibleCards=[];state.randomEligibilityConfigured=false;
function eligibleRandomCards(){const ids=deckIds();if(state.randomEligibilityConfigured)return state.randomEligibleCards.filter(id=>ids.includes(id));const programmedCards=new Set(state.rules.filter(rule=>rule.action_type==='play_named_card').map(rule=>rule.action_card_id));return ids.filter(id=>!programmedCards.has(id))}
function renderDefaultAction(){const select=$('default-action');if(!select)return;select.value=state.defaultAction;$('configure-random-cards').hidden=state.defaultAction!=='play_random_card';$('default-action-summary').textContent=state.defaultAction==='end_turn'?'Your deck will end its turn when no programmed rules match.':''}
function currentDeckPayload(){return {owner_name:$('owner').value,name:$('deck-name').value,decklist:state.deck,program:state.rules.map(rule=>{const copy={...rule};if(copy.energy_threshold!==undefined){copy.victory_points_threshold=copy.energy_threshold;delete copy.energy_threshold}return copy}),default_action:state.defaultAction,random_card_ids:eligibleRandomCards()}}
function unavailableRuleCards(rule){const deckCards=new Set(deckIds()),missing=[];if((rule.condition_type==='card_in_hand'||rule.condition_type==='card_is')&&rule.condition_card_id&&!deckCards.has(rule.condition_card_id))missing.push(rule.condition_card_id);if(rule.action_type==='play_named_card'&&rule.action_card_id&&!deckCards.has(rule.action_card_id)&&!missing.includes(rule.action_card_id))missing.push(rule.action_card_id);return missing}
renderRules=function(){const list=$('rules');list.innerHTML=state.rules.map((r,i)=>{const missing=unavailableRuleCards(r),warning=missing.length?'<small class="rule-warning">References '+esc(missing.map(name).join(' and '))+' outside this deck; this rule will be skipped.</small>':'';return '<li data-rule="'+i+'" draggable="true" class="'+(i===state.selectedRule?'selected ':'')+(missing.length?'rule-unavailable':'')+'"><span class="rule-priority">'+(i+1)+'</span><span class="rule-copy"><strong>If '+esc(conditionText(r.condition_type,r.victory_points_threshold??r.energy_threshold,r.condition_card_id,r.card_condition))+', '+esc(actionText(r.action_type,r.action_card_id))+'.</strong><small>'+(i===0?'Highest priority rule.':'Runs after the rules above.')+'</small>'+warning+'</span><button class="delete-rule" type="button" aria-label="Delete rule '+(i+1)+'" onclick="removeRuleFromProgram('+i+')">×</button></li>'}).join('')||'<li class="empty-state">No rules yet. Your default action will be used.</li>';renderDeckPreview();renderDefaultAction()}
function conditionText(type,threshold,cardId,cardCondition){if(type==='if_able')return 'if able';if(type==='card_in_hand')return name(cardId)+' is in your hand';if(type==='card_is')return name(cardId)+' is '+(cardCondition==='on_your_side_of_board'?'on your side of the board':'in your hand');if(type==='own_victory_points_at_most')return 'your Flux is '+threshold+' or less';if(type==='opponent_victory_points_at_most')return 'opponent Flux is '+threshold+' or less';if(type==='opponent_victory_points_at_least')return 'opponent Flux is '+threshold+' or more';return 'opponent Sync is '+threshold+' or less'}
function renderRandomCardPicker(){const eligible=new Set(eligibleRandomCards());$('random-card-picker').innerHTML=deckIds().map(id=>{const c=card(id),active=eligible.has(id);return '<button class="random-card-toggle '+(active?'':'deactivated')+'" type="button" data-random-card="'+esc(id)+'" aria-pressed="'+active+'"><article class="builder-card"><div class="card-titlebar"><h4>'+esc(c.display_name)+'</h4></div><div class="card-art-frame"><img src="'+esc(c.art_url)+'" alt="'+esc(c.art_alt)+'" style="object-position:'+esc(c.art_position)+'"></div><div class="card-typebar"><span>'+esc(c.card_kind_label)+'</span></div><div class="card-rules"><p>'+esc(c.effect)+'</p></div></article></button>'}).join('')}
function openRandomCardConfig(){state.randomEligibleCards=eligibleRandomCards();state.randomEligibilityConfigured=true;document.querySelectorAll('.view').forEach(panel=>panel.hidden=true);$('view-random-cards').hidden=false;renderRandomCardPicker();window.scrollTo(0,0)}
function closeRandomCardConfig(){persistSelectedDeck();setView('program');renderDefaultAction()}
$('default-action').onchange=()=>{state.defaultAction=$('default-action').value;renderDefaultAction();persistSelectedDeck()};$('configure-random-cards').onclick=openRandomCardConfig;$('confirm-random-cards').onclick=closeRandomCardConfig;
document.addEventListener('click',event=>{const cardButton=event.target.closest('[data-random-card]');if(!cardButton)return;const id=cardButton.dataset.randomCard,eligible=new Set(eligibleRandomCards());if(eligible.has(id))eligible.delete(id);else eligible.add(id);state.randomEligibleCards=deckIds().filter(cardId=>eligible.has(cardId));state.randomEligibilityConfigured=true;persistSelectedDeck();renderRandomCardPicker()},true);
$('confirm-deck').onclick=()=>{const owner=$('owner').value.trim(),selected=$('saved-decks').value,deckName=$('deck-name').value.trim();if(!owner)return;if(selected){const saved=loadSavedDecks().find(deck=>savedDeckKey(deck.owner_name,deck.name)===selected);if(!saved)return;$('deck-name').value=saved.name;state.deck={...saved.decklist};state.rules=[...saved.program];state.defaultAction=saved.default_action||'play_random_card';state.randomEligibleCards=[...(saved.random_card_ids||Object.keys(saved.decklist))];state.randomEligibilityConfigured=Array.isArray(saved.random_card_ids);state.deckKey=selected}else{if(deckName==='')return;state.deck={};state.rules=[];state.selectedRule=undefined;state.defaultAction='play_random_card';state.randomEligibleCards=[];state.randomEligibilityConfigured=false;state.deckKey=savedDeckKey(owner,deckName)}activateDeck();setTimeout(renderDefaultAction,0)};
function exportDeckCode(){const ids=state.pool.map(card=>card.card_id),index=new Map(ids.map((id,i)=>[id,i])),bytes=ids.map(id=>state.deck[id]||0);bytes.push(state.rules.length);for(const rule of state.rules){const condition={if_able:0,card_in_hand:1,own_victory_points_at_most:2,opponent_victory_points_at_most:3,opponent_sync_at_most:4,opponent_victory_points_at_least:5,card_is:6}[rule.condition_type],action={play_named_card:0,play_random_card:1,end_turn:2}[rule.action_type];if(condition===undefined||action===undefined)throw Error('This deck has an unsupported rule.');bytes.push((condition<<4)|action);if(condition===1)bytes.push(index.get(rule.condition_card_id));else if(condition===6){bytes.push(index.get(rule.condition_card_id));bytes.push(rule.card_condition==='on_your_side_of_board'?1:0)}else if(condition!==0)bytes.push(rule.victory_points_threshold??rule.energy_threshold);if(action===0)bytes.push(index.get(rule.action_card_id));}bytes.push(state.defaultAction==='end_turn'?1:0);bytes.push(eligibleRandomCards().reduce((mask,id)=>mask|(1<<index.get(id)),0));return 'CD5.'+(state.formatId||'inaugural')+'.'+btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')}

/* Keep a visitor's name in this browser only; the server never receives it until a deck is submitted. */
const playerNameStorageKey='cybernet-player-name-v1';
function savedPlayerName(){return localStorage.getItem(playerNameStorageKey)||''}
function persistPlayerName(){const value=$('owner').value.trim();if(value)localStorage.setItem(playerNameStorageKey,value);else localStorage.removeItem(playerNameStorageKey)}
$('owner').value=savedPlayerName();$('owner').oninput=()=>{persistPlayerName();renderSavedDecks()};

/* Battle log presentation keeps the selected record and its turn controls together. */
function renderBrowserLog(battle){state.logTurns=battleTurns(battle.log);state.logTurnIndex=0;state.logMode='turns';state.logBattleNumber=battle.game_number;$('log-title').textContent='Battle #'+battle.game_number;renderLogDisplay()}
function renderLogDisplay(){const turns=state.logTurns||[];const viewingTurns=state.logMode==='turns';const visible=viewingTurns?(turns[state.logTurnIndex]||[]):turns.flat();$('log').textContent=visible.join('\n');const battle='Battle #'+state.logBattleNumber;if(!viewingTurns){$('log-controls').innerHTML='<div class="log-summary"><strong>'+battle+'</strong><button data-log-mode="turns">View Turns</button></div>';return}const first=state.logTurnIndex===0,last=state.logTurnIndex===turns.length-1;$('log-controls').innerHTML='<div class="log-summary"><strong>'+battle+', Turn '+(state.logTurnIndex+1)+' of '+turns.length+'</strong><button data-log-mode="full">Show Full Log</button></div><div class="log-nav"><button class="primary" data-log-turn="-1" '+(first?'disabled':'')+'>← Prev Turn</button><button class="primary next-turn" data-log-turn="1" '+(last?'disabled':'')+'>Next Turn →</button></div>'}
$('export-deck-results').onclick=()=>$('export-deck').click();
const renderRulesAndSave=renderRules;renderRules=function(){renderRulesAndSave();persistSelectedDeck()};
const renderDeckWithRuleWarnings=renderDeck;renderDeck=function(){renderDeckWithRuleWarnings();renderRules()};

/* A compact program keeps both the builder and exported deck code readable. */
$('card-condition').onchange=renderRuleSentence;$('add-rule').onclick=()=>{const ids=deckIds(),condition=$('condition-type').value,action=$('action-type').value;if(!ids.length)return;if(state.rules.length>=10){$('status').textContent='A program can have at most 10 rules.';return}const rule={condition_type:condition,action_type:action};if(condition==='card_is'){rule.condition_card_id=$('condition-card').value;rule.card_condition=$('card-condition').value}else if(condition!=='if_able')rule.energy_threshold=+$('condition-energy').value;if(action==='play_named_card')rule.action_card_id=$('action-card').value;state.rules.push(rule);state.selectedRule=state.rules.length-1;renderRules()};
$('export-deck').onclick=async()=>{try{if(deckSize()<state.config.minimum_deck_size||deckSize()>state.config.maximum_deck_size)throw Error(deckMessage());if(state.rules.length>10)throw Error('A program can have at most 10 rules.');persistSelectedDeck();const code=exportDeckCode();await copyExportCode(code);$('status').textContent='Discord export code copied to your clipboard ('+code.length+' characters). Run /netdeck in Discord and paste it into the import box.'}catch(error){$('status').textContent='Could not export this deck. '+error.message}};

/* Generic numeric conditions keep programs declarative across cards, Flux, and Sync. */
const quantityLabels={cards_in_your_deck:'your deck',cards_in_your_hand:'your hand',cards_in_opponent_hand:"opponent's hand",your_flux:'your Flux',opponent_flux:'opponent Flux',your_sync:'your Sync',opponent_sync:'opponent Sync'},comparisonLabels={'<':'fewer than','<=':'at most','=':'exactly','>=':'at least','>':'more than'};
function quantityConditionText(rule){return quantityLabels[rule.quantity]+' is '+comparisonLabels[rule.comparison_operator]+' '+rule.quantity_threshold}
const legacyConditionTextForQuantity=conditionText;conditionText=function(type,threshold,cardId,cardCondition,quantity,comparison,quantityThreshold){return type==='quantity_compare'?quantityLabels[quantity]+' is '+comparisonLabels[comparison]+' '+quantityThreshold:legacyConditionTextForQuantity(type,threshold,cardId,cardCondition)};
function renderQuantityRuleSentence(){const type=$('condition-type').value,action=$('action-type').value,actionCard=$('action-card').value;if(type==='quantity_compare')$('rule-sentence').textContent='If '+quantityLabels[$('condition-quantity').value]+' is '+comparisonLabels[$('comparison-operator').value]+' '+$('quantity-threshold').value+', '+actionText(action,actionCard)+'.';else $('rule-sentence').textContent='If '+conditionText(type,$('condition-energy').value,$('condition-card').value,$('card-condition').value)+', '+actionText(action,actionCard)+'.'}
function renderQuantityConditionParameters(){const quantity=$('condition-type').value==='quantity_compare';$('quantity-wrap').hidden=!quantity;$('comparison-wrap').hidden=!quantity;$('quantity-threshold-wrap').hidden=!quantity;$('condition-card-wrap').hidden=quantity||$('condition-type').value!=='card_is';$('card-condition-wrap').hidden=quantity||$('condition-type').value!=='card_is';$('condition-energy-wrap').hidden=quantity||$('condition-type').value==='card_is'||$('condition-type').value==='if_able';renderQuantityRuleSentence()}
renderRules=function(){const list=$('rules');list.innerHTML=state.rules.map((r,i)=>{const missing=unavailableRuleCards(r),warning=missing.length?'<small class="rule-warning">References '+esc(missing.map(name).join(' and '))+' outside this deck; this rule will be skipped.</small>':'',condition=r.condition_type==='quantity_compare'?quantityConditionText(r):conditionText(r.condition_type,r.victory_points_threshold??r.energy_threshold,r.condition_card_id,r.card_condition);return '<li data-rule="'+i+'" draggable="true" class="'+(i===state.selectedRule?'selected ':'')+(missing.length?'rule-unavailable':'')+'"><span class="rule-priority">'+(i+1)+'</span><span class="rule-copy"><strong>If '+esc(condition)+', '+esc(actionText(r.action_type,r.action_card_id))+'.</strong><small>'+(i===0?'Highest priority rule.':'Runs after the rules above.')+'</small>'+warning+'</span><button class="delete-rule" type="button" aria-label="Delete rule '+(i+1)+'" onclick="removeRuleFromProgram('+i+')">×</button></li>'}).join('')||'<li class="empty-state">No rules yet. Your default action will be used.</li>';renderDeckPreview();renderDefaultAction();persistSelectedDeck()};
exportDeckCode=function(){const ids=state.pool.map(card=>card.card_id),index=new Map(ids.map((id,i)=>[id,i])),bytes=ids.map(id=>state.deck[id]||0),conditions={if_able:0,card_in_hand:1,own_victory_points_at_most:2,opponent_victory_points_at_most:3,opponent_sync_at_most:4,opponent_victory_points_at_least:5,card_is:6,quantity_compare:7},quantities={cards_in_your_deck:0,cards_in_your_hand:1,cards_in_opponent_hand:2,your_flux:3,opponent_flux:4,your_sync:5,opponent_sync:6},comparisons={'<':0,'<=':1,'=':2,'>=':3,'>':4};bytes.push(state.rules.length);for(const rule of state.rules){const condition=conditions[rule.condition_type],action={play_named_card:0,play_random_card:1,end_turn:2}[rule.action_type];if(condition===undefined||action===undefined)throw Error('This deck has an unsupported rule.');bytes.push((condition<<4)|action);if(condition===1)bytes.push(index.get(rule.condition_card_id));else if(condition===6){bytes.push(index.get(rule.condition_card_id),rule.card_condition==='on_your_side_of_board'?1:0)}else if(condition===7){const threshold=Number(rule.quantity_threshold);if(!Number.isInteger(threshold)||threshold<0||threshold>65535)throw Error('Quantity conditions must use a whole number from 0 through 65,535.');bytes.push(quantities[rule.quantity],comparisons[rule.comparison_operator],threshold>>8,threshold&255)}else if(condition!==0)bytes.push(rule.victory_points_threshold??rule.energy_threshold);if(action===0)bytes.push(index.get(rule.action_card_id));}bytes.push(state.defaultAction==='end_turn'?1:0,eligibleRandomCards().reduce((mask,id)=>mask|(1<<index.get(id)),0));return 'CD6.'+(state.formatId||'inaugural')+'.'+btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')};
$('condition-type').onchange=renderQuantityConditionParameters;$('condition-card').onchange=renderQuantityRuleSentence;$('card-condition').onchange=renderQuantityRuleSentence;$('condition-energy').onchange=renderQuantityRuleSentence;$('condition-quantity').onchange=renderQuantityRuleSentence;$('comparison-operator').onchange=renderQuantityRuleSentence;$('quantity-threshold').oninput=renderQuantityRuleSentence;$('action-type').onchange=()=>{renderRuleSelectors();renderQuantityRuleSentence()};$('action-card').onchange=renderQuantityRuleSentence;
$('add-rule').onclick=()=>{const ids=deckIds(),condition=$('condition-type').value,action=$('action-type').value;if(!ids.length)return;if(state.rules.length>=10){$('status').textContent='A program can have at most 10 rules.';return}const rule={condition_type:condition,action_type:action};if(condition==='card_is'){rule.condition_card_id=$('condition-card').value;rule.card_condition=$('card-condition').value}else if(condition==='quantity_compare'){const threshold=Number($('quantity-threshold').value);if(!Number.isSafeInteger(threshold)||threshold<0){$('status').textContent='Quantity conditions need a whole number of 0 or more.';return}rule.quantity=$('condition-quantity').value;rule.comparison_operator=$('comparison-operator').value;rule.quantity_threshold=threshold}else if(condition!=='if_able')rule.energy_threshold=+$('condition-energy').value;if(action==='play_named_card')rule.action_card_id=$('action-card').value;state.rules.push(rule);state.selectedRule=state.rules.length-1;renderRules()};
renderQuantityConditionParameters();

/* The local host and Pages both provide this exact, public-safe payload. */
const tournamentState={data:null,matchIndex:null,battlePage:0,turns:[],turn:0};
function tournamentEntry(id){return tournamentState.data.decks.find(entry=>String(entry.discord_user_id)===String(id))}
function tournamentName(id){const entry=tournamentEntry(id);return entry?entry.player_name:String(id)}
function tournamentRule(rule){const condition=rule.condition_type==='if_able'?'If able':rule.condition_type==='card_in_hand'?'If '+rule.condition_card_id+' is in hand':rule.condition_type==='own_victory_points_at_most'?'If Flux is '+rule.victory_points_threshold+' or less':rule.condition_type==='opponent_victory_points_at_most'?'If opponent Flux is '+rule.victory_points_threshold+' or less':rule.condition_type==='opponent_victory_points_at_least'?'If opponent Flux is '+rule.victory_points_threshold+' or more':'If opponent Sync is '+rule.victory_points_threshold+' or less';const action=rule.action_type==='end_turn'?'end the turn':rule.action_type==='play_random_card'?'play a random eligible card':'play '+rule.action_card_id;return condition+', '+action+'.'}
function tournamentBack(label,target){return '<button type="button" data-tournament-back="'+target+'">&larr; '+label+'</button>'}
function renderLatestTournament(data){const panel=$('latest-tournament');tournamentState.data=data;if(!data||!data.snapshot_id){panel.innerHTML='<p class="eyebrow">TOURNAMENT</p><p class="sub">No published tournament yet.</p>';return}panel.innerHTML='<p class="eyebrow">TOURNAMENT</p><button class="primary tournament-open" type="button" data-tournament-open>View tournament results</button>'}
async function openTournamentResults(){const data=tournamentState.data;if(data?.snapshot_id&&data.battles===undefined){try{data.battles=await fetch('data/tournaments/'+encodeURIComponent(data.snapshot_id)+'/battles.json').then(response=>response.json())}catch(_error){data.battles=[]}}renderTournamentResults()}
function renderTournamentResults(){const data=tournamentState.data,panel=$('latest-tournament'),standings=data.standings||[],pairings=data.battles||[];const rows=standings.map((row,index)=>'<tr tabindex="0" data-tournament-deck="'+esc(row.discord_user_id)+'"><td>'+(index+1)+'</td><td>'+esc(row.player_name)+'</td><td>'+esc(row.deck_name)+'</td><td>'+row.total_wins+'</td></tr>').join('');const matchups=pairings.map((pair,index)=>{const firstWins=pair.battles.filter(b=>b.winner_id==='first').length,secondWins=pair.battles.filter(b=>b.winner_id==='second').length,draws=pair.battles.length-firstWins-secondWins;return '<tr tabindex="0" data-tournament-match="'+index+'"><td>'+esc(tournamentName(pair.first_discord_user_id))+'</td><td>'+esc(tournamentName(pair.second_discord_user_id))+'</td><td>'+firstWins+'-'+secondWins+'-'+draws+'</td><td>'+pair.battles.length+'</td></tr>'}).join('');panel.innerHTML='<div class="section-heading"><div><p class="eyebrow">Latest official tournament</p><h2>Results</h2></div>'+tournamentBack('Close','summary')+'</div><div class="table-scroll"><table><thead><tr><th>Rank</th><th>Player</th><th>Deck</th><th>Wins</th></tr></thead><tbody>'+rows+'</tbody></table></div><h3 class="tournament-heading">Matchups</h3><p class="sub">Choose a matchup to inspect its battles.</p><div class="table-scroll"><table><thead><tr><th>First player</th><th>Second player</th><th>W-L-D</th><th>Battles</th></tr></thead><tbody>'+matchups+'</tbody></table></div>'}
function renderTournamentDeck(id){const entry=tournamentEntry(id),panel=$('latest-tournament');if(!entry)return;const submission=entry.submission,deck=Object.entries(submission.decklist).map(([card,count])=>'<li><strong>'+esc(card)+'</strong> &times; '+count+'</li>').join(''),rules=(submission.program||[]).map((rule,index)=>'<li><strong>'+(index+1)+'.</strong> '+esc(tournamentRule(rule))+'</li>').join('')||'<li>No programmed rules; uses the default action.</li>';panel.innerHTML='<div class="section-heading"><div><p class="eyebrow">Tournament deck</p><h2>'+esc(entry.player_name)+' &middot; '+esc(submission.name)+'</h2></div>'+tournamentBack('Tournament results','results')+'</div><div class="tournament-deck-grid"><section><h3>Decklist</h3><ul>'+deck+'</ul></section><section><h3>Program</h3><ol>'+rules+'</ol><p class="sub">Default action: '+esc(submission.default_action||'play_random_card')+'.</p></section></div>'}
function renderTournamentMatch(index){const pair=tournamentState.data.battles[index],panel=$('latest-tournament');if(!pair)return;tournamentState.matchIndex=index;const pageSize=25,pages=Math.max(1,Math.ceil(pair.battles.length/pageSize)),start=tournamentState.battlePage*pageSize,battles=pair.battles.slice(start,start+pageSize),rows=battles.map(b=>'<tr tabindex="0" data-tournament-battle="'+b.game_number+'"><td>'+b.game_number+'</td><td>'+esc(b.winner_id===null?'Draw':b.winner_id==='first'?tournamentName(pair.first_discord_user_id):tournamentName(pair.second_discord_user_id))+'</td><td>'+b.first_victory_points+'-'+b.second_victory_points+'</td><td>'+esc(b.end_reason)+'</td></tr>').join('');panel.innerHTML='<div class="section-heading"><div><p class="eyebrow">Tournament matchup</p><h2>'+esc(tournamentName(pair.first_discord_user_id))+' vs. '+esc(tournamentName(pair.second_discord_user_id))+'</h2></div>'+tournamentBack('Tournament results','results')+'</div><p class="sub">Select a battle to replay its player-facing log.</p><div class="table-scroll"><table><thead><tr><th>#</th><th>Winner</th><th>Flux</th><th>Reason</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="page"><button data-tournament-page="-1" '+(tournamentState.battlePage===0?'disabled':'')+'>← Previous</button><span> Battles '+(start+1)+'–'+Math.min(start+pageSize,pair.battles.length)+' of '+pair.battles.length+'</span><button data-tournament-page="1" '+(tournamentState.battlePage+1>=pages?'disabled':'')+'>Next →</button></div>'}
function tournamentNarration(event,first,second){const name=id=>id==='first'?first:second;if(event.endsWith(' | turn_start'))return name(event.split(' | ')[0])+' begins their turn.';if(event.includes(' | draw'))return name(event.split(' | ')[0])+' drew a card.';if(event.includes(' | play:'))return name(event.split(' | ')[0])+' played '+event.split('play:')[1]+'.';if(event.includes(' | sync:'))return name(event.split(' | ')[0])+' now has '+event.split(':').at(-1)+' Sync.';if(event.endsWith(' | end_turn_effect'))return name(event.split(' | ')[0])+' ended their turn from a card effect.';if(event.endsWith(' | end_turn_action'))return name(event.split(' | ')[0])+' ended their turn.';if(event.startsWith('system | battle_end:')){const [,winner,reason]=event.split(':');return winner==='draw'?'The battle ended in a draw ('+reason+').':name(winner)+' won by '+reason+'.'}return ''}
function tournamentTurns(log,first,second){const turns=[];let current=[];for(const event of log){if(event.endsWith(' | turn_start')){current=[];turns.push(current)}const line=tournamentNarration(event,first,second);if(line)current.push(line)}return turns.filter(turn=>turn.length)}
async function renderTournamentBattle(number){const pair=tournamentState.data.battles[tournamentState.matchIndex],record=pair.battles.find(b=>b.game_number===Number(number)),first=tournamentEntry(pair.first_discord_user_id),second=tournamentEntry(pair.second_discord_user_id),panel=$('latest-tournament');if(!record||!first||!second)return;panel.innerHTML='<p class="eyebrow">Tournament battle</p><h2>Replaying battle '+record.game_number+'&hellip;</h2>';try{const [{replayBattle},{CARD_POOL}]=await Promise.all([import(new URL('engine/engine.js',location.href)),import(new URL('engine/cards.js',location.href))]);const battle=replayBattle(first.submission,second.submission,CARD_POOL,record.seed,undefined,record.starting_player);tournamentState.turns=tournamentTurns(battle.log,first.player_name,second.player_name);tournamentState.turn=0;renderTournamentLog()}catch(error){panel.innerHTML='<p class="eyebrow">Tournament battle</p><h2>Replay unavailable</h2><p class="sub">'+esc(error.message||String(error))+'</p>'+tournamentBack('Matchup','match')}}
function renderTournamentLog(){const pair=tournamentState.data.battles[tournamentState.matchIndex],panel=$('latest-tournament'),turns=tournamentState.turns,turn=turns[tournamentState.turn]||[];panel.innerHTML='<div class="section-heading"><div><p class="eyebrow">Tournament battle log</p><h2>'+esc(tournamentName(pair.first_discord_user_id))+' vs. '+esc(tournamentName(pair.second_discord_user_id))+'</h2></div>'+tournamentBack('Matchup','match')+'</div><pre class="tournament-log">'+esc(turn.join('\n'))+'</pre><div class="log-nav"><button data-tournament-turn="-1" '+(tournamentState.turn===0?'disabled':'')+'>← Previous turn</button><span>Turn '+(tournamentState.turn+1)+' of '+turns.length+'</span><button data-tournament-turn="1" '+(tournamentState.turn+1>=turns.length?'disabled':'')+'>Next turn →</button></div>'}
document.addEventListener('click',event=>{const target=event.target.closest('[data-tournament-open],[data-tournament-deck],[data-tournament-match],[data-tournament-battle],[data-tournament-page],[data-tournament-turn],[data-tournament-back]');if(!target)return;event.preventDefault();if('tournamentOpen' in target.dataset)return openTournamentResults();if(target.dataset.tournamentDeck)return renderTournamentDeck(target.dataset.tournamentDeck);if(target.dataset.tournamentMatch){tournamentState.battlePage=0;return renderTournamentMatch(+target.dataset.tournamentMatch)}if(target.dataset.tournamentBattle)return renderTournamentBattle(target.dataset.tournamentBattle);if(target.dataset.tournamentPage){tournamentState.battlePage=Math.max(0,tournamentState.battlePage+Number(target.dataset.tournamentPage));return renderTournamentMatch(tournamentState.matchIndex)}if(target.dataset.tournamentTurn){tournamentState.turn=Math.max(0,Math.min(tournamentState.turns.length-1,tournamentState.turn+Number(target.dataset.tournamentTurn)));return renderTournamentLog()}if(target.dataset.tournamentBack==='summary')return closeTournamentView();if(target.dataset.tournamentBack==='results')return renderTournamentResults();if(target.dataset.tournamentBack==='match')return renderTournamentMatch(tournamentState.matchIndex)},true);
fetch('data/tournaments/latest.json').then(response=>response.ok?response.json():Promise.reject()).then(renderLatestTournament).catch(()=>renderLatestTournament(null));

/* Tournament presentation intentionally mirrors the simulation result, matchup, and log views. */
function tournamentPanel(){return $('tournament-view')}
function tournamentCardName(cardId){const cards=tournamentState.data?.manifest?.cards||[];return cards.find(card=>card.card_id===cardId)?.display_name||String(cardId).split('_').map(word=>word.toUpperCase()==='L'?word.toUpperCase():word.charAt(0).toUpperCase()+word.slice(1)).join(' ')}
function tournamentActionName(action){return action==='end_turn'?'End Turn':action==='play_random_card'?'Play a Random Eligible Card':'Play '+tournamentCardName(action)}
function tournamentRuleText(rule){const condition=rule.condition_type==='if_able'?'If able':rule.condition_type==='card_in_hand'?'If '+tournamentCardName(rule.condition_card_id)+' is in your hand':rule.condition_type==='card_is'?'If '+tournamentCardName(rule.condition_card_id)+' is '+(rule.card_condition==='on_your_side_of_board'?'on your side of the board':'in your hand'):rule.condition_type==='own_victory_points_at_most'?'If Flux is '+rule.victory_points_threshold+' or less':rule.condition_type==='opponent_victory_points_at_most'?'If opponent Flux is '+rule.victory_points_threshold+' or less':rule.condition_type==='opponent_victory_points_at_least'?'If opponent Flux is '+rule.victory_points_threshold+' or more':'If opponent Sync is '+rule.victory_points_threshold+' or less';const action=rule.action_type==='play_named_card'?'Play '+tournamentCardName(rule.action_card_id):tournamentActionName(rule.action_type);return condition+', '+action+'.'}
function closeTournamentView(){tournamentPanel().hidden=true;$('latest-tournament').hidden=false;if(tournamentState.returnView){$('workflow-nav').hidden=false;$('status').hidden=false;setView(tournamentState.returnView)}else $('deck-setup').hidden=false}
openTournamentResults=async function(){const data=tournamentState.data;if(data?.snapshot_id&&data.battles===undefined){try{data.battles=await fetch('data/tournaments/'+encodeURIComponent(data.snapshot_id)+'/battles.json').then(response=>response.json())}catch(_error){data.battles=[]}}tournamentState.returnView=state.deckReady?state.view:null;$('latest-tournament').hidden=true;$('deck-setup').hidden=true;$('workflow-nav').hidden=true;$('status').hidden=true;document.querySelectorAll('.view').forEach(view=>view.hidden=true);tournamentPanel().hidden=false;renderTournamentResults()}
renderTournamentResults=function(){const data=tournamentState.data,panel=tournamentPanel(),standings=data.standings||[],rank=new Map(standings.map((row,index)=>[String(row.discord_user_id),index])),pairings=(data.battles||[]).map((pair,index)=>({pair,index})).sort((left,right)=>Math.min(rank.get(String(left.pair.first_discord_user_id)),rank.get(String(left.pair.second_discord_user_id)))-Math.min(rank.get(String(right.pair.first_discord_user_id)),rank.get(String(right.pair.second_discord_user_id)))||Math.max(rank.get(String(left.pair.first_discord_user_id)),rank.get(String(left.pair.second_discord_user_id)))-Math.max(rank.get(String(right.pair.first_discord_user_id)),rank.get(String(right.pair.second_discord_user_id))));const rows=standings.map((row,index)=>'<tr tabindex="0" data-tournament-deck="'+esc(row.discord_user_id)+'"><td>'+(index+1)+'</td><td>'+esc(row.player_name)+'</td><td>'+esc(row.deck_name)+'</td><td>'+row.total_wins+'</td></tr>').join('');const matchups=pairings.map(({pair,index})=>{const firstWins=pair.battles.filter(b=>b.winner_id==='first').length,secondWins=pair.battles.filter(b=>b.winner_id==='second').length,draws=pair.battles.length-firstWins-secondWins;return '<tr tabindex="0" data-tournament-match="'+index+'"><td>'+esc(tournamentName(pair.first_discord_user_id))+'</td><td>'+esc(tournamentName(pair.second_discord_user_id))+'</td><td>'+firstWins+'-'+secondWins+'-'+draws+'</td><td>'+pair.battles.length+'</td></tr>'}).join('');panel.innerHTML='<div class="section-heading"><div><h2>Results</h2><p class="sub">Choose a deck to view it.</p></div>'+tournamentBack('Back','summary')+'</div><div class="table-scroll"><table><thead><tr><th>Rank</th><th>Player</th><th>Deck</th><th>Wins</th></tr></thead><tbody>'+rows+'</tbody></table></div><h3 class="tournament-heading">Matchups</h3><p class="sub">Select a matchup to inspect its battles.</p><div class="table-scroll"><table><thead><tr><th>First player</th><th>Second player</th><th>W-L-D</th><th>Battles</th></tr></thead><tbody>'+matchups+'</tbody></table></div>'}
renderTournamentDeck=function(id){const entry=tournamentEntry(id),panel=tournamentPanel();if(!entry)return;const submission=entry.submission,deck=Object.entries(submission.decklist).map(([cardId,count])=>'<li><strong>'+esc(tournamentCardName(cardId))+'</strong> &times; '+count+'</li>').join(''),rules=(submission.program||[]).map((rule,index)=>'<li><strong>'+(index+1)+'.</strong> '+esc(tournamentRuleText(rule))+'</li>').join('')||'<li>No programmed rules; uses the default action.</li>';panel.innerHTML='<div class="section-heading"><div><p class="eyebrow">Tournament deck</p><h2>'+esc(entry.player_name)+' &middot; '+esc(submission.name)+'</h2></div>'+tournamentBack('Tournament results','results')+'</div><div class="tournament-deck-grid"><section><h3>Decklist</h3><ul>'+deck+'</ul></section><section><h3>Program</h3><ol>'+rules+'</ol><p class="sub">Default action: '+esc(tournamentActionName(submission.default_action||'play_random_card'))+'.</p></section></div>'}
renderTournamentMatch=function(index){const pair=tournamentState.data.battles[index],panel=tournamentPanel();if(!pair)return;tournamentState.matchIndex=index;const pageSize=10,pages=Math.max(1,Math.ceil(pair.battles.length/pageSize)),start=tournamentState.battlePage*pageSize,battles=pair.battles.slice(start,start+pageSize),rows=battles.map(b=>'<tr tabindex="0" data-tournament-battle="'+b.game_number+'"><td>'+b.game_number+'</td><td>'+esc(b.winner_id===null?'Draw':b.winner_id==='first'?tournamentName(pair.first_discord_user_id):tournamentName(pair.second_discord_user_id))+'</td><td>'+b.first_victory_points+'-'+b.second_victory_points+'</td><td>'+esc(b.end_reason)+'</td></tr>').join('');panel.innerHTML='<div class="subsection-heading"><div><p class="eyebrow">Selected matchup</p><h3>'+esc(tournamentName(pair.first_discord_user_id))+' vs. '+esc(tournamentName(pair.second_discord_user_id))+'</h3></div>'+tournamentBack('Results','results')+'</div><p class="sub">Select a battle to open its player-facing log.</p><div class="page"><span class="page-label">Battles '+(start+1)+'–'+Math.min(start+battles.length,pair.battles.length)+' of '+pair.battles.length+'</span><button data-tournament-page="-1" '+(tournamentState.battlePage===0?'disabled':'')+'>← Previous</button><button data-tournament-page="1" '+(tournamentState.battlePage+1>=pages?'disabled':'')+'>Next →</button></div><div class="table-scroll"><table><thead><tr><th>#</th><th>Winner</th><th>Score</th><th>Reason</th></tr></thead><tbody>'+rows+'</tbody></table></div>'}
tournamentNarration=function(event,first,second){const player=id=>id==='first'?first:second;if(event.endsWith(' | turn_start'))return player(event.split(' | ')[0])+' begins their turn.';if(event.includes(' | draw'))return player(event.split(' | ')[0])+' drew a card.';if(event.includes(' | play:'))return player(event.split(' | ')[0])+' played '+tournamentCardName(event.split('play:')[1])+'.';if(event.includes(' | sync:'))return player(event.split(' | ')[0])+' now has '+event.split(':').at(-1)+' Sync.';if(event.endsWith(' | end_turn_effect'))return player(event.split(' | ')[0])+' ended their turn from a card effect.';if(event.endsWith(' | end_turn_action'))return player(event.split(' | ')[0])+' ended their turn.';if(event.startsWith('system | battle_end:')){const [,winner,reason]=event.split(':');return winner==='draw'?'The battle ended in a draw ('+reason+').':player(winner)+' won by '+reason+'.'}return ''}
renderTournamentBattle=async function(number){const pair=tournamentState.data.battles[tournamentState.matchIndex],record=pair.battles.find(b=>b.game_number===Number(number)),first=tournamentEntry(pair.first_discord_user_id),second=tournamentEntry(pair.second_discord_user_id),panel=tournamentPanel();if(!record||!first||!second)return;panel.innerHTML='<div class="section-heading"><div><h2>Battle Logs</h2><p class="sub">Replaying Battle #'+record.game_number+'&hellip;</p></div>'+tournamentBack('Back to battles','match')+'</div>';try{const [{replayBattle},{CARD_POOL}]=await Promise.all([import(new URL('engine/engine.js',location.href)),import(new URL('engine/cards.js',location.href))]);const battle=replayBattle(first.submission,second.submission,CARD_POOL,record.seed,undefined,record.starting_player);tournamentState.turns=tournamentTurns(battle.log,first.player_name,second.player_name);tournamentState.turn=0;renderTournamentLog()}catch(error){panel.innerHTML='<h2>Battle Logs</h2><p class="sub">Replay unavailable: '+esc(error.message||String(error))+'</p>'+tournamentBack('Back to battles','match')}}
renderTournamentLog=function(){const pair=tournamentState.data.battles[tournamentState.matchIndex],panel=tournamentPanel(),turns=tournamentState.turns,turn=turns[tournamentState.turn]||[],battleNumber=pair.battles.find(b=>b.seed===undefined)||null;panel.innerHTML='<div class="section-heading"><div><h2>Battle Logs</h2><p class="sub">Player-facing narration for the selected battle.</p></div>'+tournamentBack('Back to battles','match')+'</div><div class="log-controls"><div class="log-summary"><strong>Battle #'+(tournamentState.selectedBattleNumber||'?')+', Turn '+(tournamentState.turn+1)+' of '+turns.length+'</strong></div><div class="log-nav"><button class="primary" data-tournament-turn="-1" '+(tournamentState.turn===0?'disabled':'')+'>← Prev Turn</button><button class="primary next-turn" data-tournament-turn="1" '+(tournamentState.turn+1>=turns.length?'disabled':'')+'>Next Turn →</button></div></div><pre class="tournament-log">'+esc(turn.join('\n'))+'</pre>'}
const originalTournamentBattle=renderTournamentBattle;renderTournamentBattle=async function(number){tournamentState.selectedBattleNumber=Number(number);return originalTournamentBattle(number)};

/* Frozen tournament programs use the same readable numeric-condition sentence. */
tournamentRuleText=function(rule){const condition=rule.condition_type==='quantity_compare'?'If '+quantityConditionText(rule):rule.condition_type==='if_able'?'If able':rule.condition_type==='card_in_hand'?'If '+tournamentCardName(rule.condition_card_id)+' is in your hand':rule.condition_type==='card_is'?'If '+tournamentCardName(rule.condition_card_id)+' is '+(rule.card_condition==='on_your_side_of_board'?'on your side of the board':'in your hand'):rule.condition_type==='own_victory_points_at_most'?'If Flux is '+rule.victory_points_threshold+' or less':rule.condition_type==='opponent_victory_points_at_most'?'If opponent Flux is '+rule.victory_points_threshold+' or less':rule.condition_type==='opponent_victory_points_at_least'?'If opponent Flux is '+rule.victory_points_threshold+' or more':'If opponent Sync is '+rule.victory_points_threshold+' or less';const action=rule.action_type==='play_named_card'?'Play '+tournamentCardName(rule.action_card_id):tournamentActionName(rule.action_type);return condition+', '+action+'.'};

function tournamentDeckCardName(cardId){return '<span class="tournament-card-name" tabindex="0" data-tournament-card-preview="'+esc(cardId)+'">'+esc(tournamentCardName(cardId))+'</span>'}
function tournamentCardPreview(cardId){const current=card(cardId);return '<article class="builder-card"><div class="card-titlebar"><h4>'+esc(current.display_name)+'</h4></div><div class="card-art-frame">'+(current.art_url?'<img src="'+esc(current.art_url)+'" alt="'+esc(current.art_alt||current.display_name)+'" style="object-position:'+esc(current.art_position||'center')+'">':'')+'</div><div class="card-typebar"><span>'+esc(current.card_kind_label||'Card')+'</span></div><div class="card-rules"><p>'+esc(current.effect)+'</p></div></article>'}
function showTournamentCardPreview(target){document.querySelectorAll('.tournament-card-tooltip').forEach(node=>node.remove());const preview=document.createElement('div');preview.className='tournament-card-tooltip';preview.innerHTML=tournamentCardPreview(target.dataset.tournamentCardPreview);document.body.append(preview);const rect=target.getBoundingClientRect(),left=Math.min(window.innerWidth-266,Math.max(8,rect.right+12)),top=Math.min(window.innerHeight-310,Math.max(8,rect.top));preview.style.left=left+'px';preview.style.top=top+'px'}
function hideTournamentCardPreview(){document.querySelectorAll('.tournament-card-tooltip').forEach(node=>node.remove())}
renderTournamentDeck=function(id){const entry=tournamentEntry(id),panel=tournamentPanel();if(!entry)return;const submission=entry.submission,deck=Object.entries(submission.decklist).map(([cardId,count])=>'<li><strong>'+tournamentDeckCardName(cardId)+'</strong> &times; '+count+'</li>').join(''),rules=(submission.program||[]).map((rule,index)=>'<li><strong>'+(index+1)+'.</strong> '+esc(tournamentRuleText(rule))+'</li>').join('')||'<li>No programmed rules; uses the default action.</li>';panel.innerHTML='<div class="section-heading"><div><p class="eyebrow">Tournament deck</p><h2>'+esc(entry.player_name)+' &middot; '+esc(submission.name)+'</h2></div>'+tournamentBack('Tournament results','results')+'</div><div class="tournament-deck-grid"><section><h3>Decklist</h3><ul>'+deck+'</ul></section><section><h3>Program</h3><ol>'+rules+'</ol><p class="sub">Default action: '+esc(tournamentActionName(submission.default_action||'play_random_card'))+'.</p></section></div>'}
document.addEventListener('mouseover',event=>{const target=event.target.closest('[data-tournament-card-preview]');if(target)showTournamentCardPreview(target)});document.addEventListener('mouseout',event=>{if(event.target.closest('[data-tournament-card-preview]'))hideTournamentCardPreview()});document.addEventListener('focusin',event=>{const target=event.target.closest('[data-tournament-card-preview]');if(target)showTournamentCardPreview(target)});document.addEventListener('focusout',event=>{if(event.target.closest('[data-tournament-card-preview]'))hideTournamentCardPreview()});

/* Dynamic imports must resolve beside app.js so mounted Tailscale paths work. */
renderTournamentBattle=async function(number){const pair=tournamentState.data.battles[tournamentState.matchIndex],record=pair.battles.find(b=>b.game_number===Number(number)),first=tournamentEntry(pair.first_discord_user_id),second=tournamentEntry(pair.second_discord_user_id),panel=tournamentPanel();if(!record||!first||!second)return;tournamentState.selectedBattleNumber=Number(number);panel.innerHTML='<div class="section-heading"><div><h2>Battle Logs</h2><p class="sub">Replaying Battle #'+record.game_number+'&hellip;</p></div>'+tournamentBack('Back to battles','match')+'</div>';try{const appScript=document.querySelector('script[src$="/app.js"]'),assetBase=appScript?appScript.src:location.href;const [{replayBattle},{CARD_POOL}]=await Promise.all([import(new URL('engine/engine.js',assetBase)),import(new URL('engine/cards.js',assetBase))]);const battle=replayBattle(first.submission,second.submission,CARD_POOL,record.seed,undefined,record.starting_player);tournamentState.turns=tournamentTurns(battle.log,first.player_name,second.player_name);tournamentState.turn=0;renderTournamentLog()}catch(error){panel.innerHTML='<h2>Battle Logs</h2><p class="sub">Replay unavailable: '+esc(error.message||String(error))+'</p>'+tournamentBack('Back to battles','match')}};

async function tournamentRulesFingerprint(){const script=document.querySelector('script[src$="/app.js"]'),base=script?script.src:location.href,files=await Promise.all(['engine/engine.js','engine/cards.js'].map(path=>fetch(new URL(path,base)).then(response=>{if(!response.ok)throw Error('rules asset unavailable');return response.arrayBuffer()}))),bytes=new Uint8Array(files[0].byteLength+1+files[1].byteLength);bytes.set(new Uint8Array(files[0]));bytes[files[0].byteLength]=0;bytes.set(new Uint8Array(files[1]),files[0].byteLength+1);const digest=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(digest)).map(value=>value.toString(16).padStart(2,'0')).join('')}
