/* Turn counts are retained with each compact battle record, so reports do not need a replay. */
function averageTurns(battles){return battles.length&&battles.every(battle=>Number.isInteger(battle.turn_count))?(battles.reduce((total,battle)=>total+battle.turn_count,0)/battles.length).toFixed(1):'—'}
