renderTournamentMatch=function(index){const pair=tournamentState.data.battles[index],panel=tournamentPanel();if(!pair)return;tournamentState.matchIndex=index;const pageSize=25,pages=Math.max(1,Math.ceil(pair.battles.length/pageSize)),start=tournamentState.battlePage*pageSize,battles=pair.battles.slice(start,start+pageSize),rows=battles.map(b=>'<tr tabindex="0" data-tournament-battle="'+b.game_number+'"><td>'+b.game_number+'</td><td>'+esc(b.winner_id===null?'Draw':b.winner_id==='first'?tournamentName(pair.first_discord_user_id):tournamentName(pair.second_discord_user_id))+'</td><td>'+b.first_victory_points+'-'+b.second_victory_points+'</td><td>'+b.turn_count+'</td><td>'+esc(b.end_reason)+'</td></tr>').join('');panel.innerHTML='<div class="section-heading"><div><p class="eyebrow">Tournament matchup</p><h2>'+esc(tournamentName(pair.first_discord_user_id))+' vs. '+esc(tournamentName(pair.second_discord_user_id))+'</h2></div>'+tournamentBack('Tournament results','results')+'</div><p class="sub">Select a battle to replay its player-facing log.</p><div class="table-scroll"><table><thead><tr><th>#</th><th>Winner</th><th>Flux</th><th>Turns</th><th>Reason</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="page"><button data-tournament-page="-1" '+(tournamentState.battlePage===0?'disabled':'')+'>&larr; Previous</button><span>Battles '+(start+1)+' to '+Math.min(start+pageSize,pair.battles.length)+' of '+pair.battles.length+'</span><button data-tournament-page="1" '+(tournamentState.battlePage+1>=pages?'disabled':'')+'>Next &rarr;</button></div>'}
