/* Reactions are a separate deterministic policy, never a Main-phase action. */
state.reactions=[];
const reactionPayload=currentDeckPayload;currentDeckPayload=function(){return {...reactionPayload(),reactions:state.reactions.map(rule=>({...rule}))}};
const reactionCards=()=>deckIds().filter(id=>{const definition=card(id),kind=String(definition.card_kind||'').toLowerCase(),label=String(definition.card_kind_label||'').toLowerCase();return kind==='glitch'||label==='glitch'});
function renderReactionProgram(){const ids=reactionCards();options($('reaction-card'),ids,ids[0]);$('add-reaction').disabled=!ids.length;$('reactions').innerHTML=state.reactions.map((rule,index)=>'<li><span class="rule-priority">'+(index+1)+'</span><span class="rule-copy"><strong>When opponent would gain Flux '+({'>':'more than','>=':'at least','=':'exactly','<=':'at most','<':'fewer than'})[rule.comparison_operator]+' '+rule.quantity_threshold+', play '+esc(name(rule.action_card_id))+'.</strong><small>'+(index===0?'Highest priority reaction.':'Runs after the reactions above.')+'</small></span><button type="button" data-move-reaction="'+index+'" data-reaction-direction="-1" '+(index===0?'disabled':'')+' aria-label="Move reaction '+(index+1)+' up">↑</button><button type="button" data-move-reaction="'+index+'" data-reaction-direction="1" '+(index+1===state.reactions.length?'disabled':'')+' aria-label="Move reaction '+(index+1)+' down">↓</button><button type="button" data-remove-reaction="'+index+'" aria-label="Delete reaction '+(index+1)+'">×</button></li>').join('')||'<li class="empty-state">No reactions yet.</li>'}
const renderMainRulesWithReactions=renderRules;renderRules=function(){renderMainRulesWithReactions();renderReactionProgram()};
$('add-reaction').onclick=()=>{const threshold=Number($('reaction-threshold').value),ids=reactionCards();if(!ids.length)return;if(!Number.isSafeInteger(threshold)||threshold<0){$('status').textContent='Reaction amounts need a whole number of 0 or more.';return}if(state.reactions.length>=10){$('status').textContent='A reaction program can have at most 10 rules.';return}state.reactions.push({trigger_type:'opponent_would_gain_flux',comparison_operator:$('reaction-comparison').value,quantity_threshold:threshold,action_card_id:$('reaction-card').value});renderReactionProgram();persistSelectedDeck()};
document.addEventListener('click',event=>{const button=event.target.closest('[data-remove-reaction],[data-move-reaction]');if(!button)return;if(button.dataset.removeReaction!==undefined)state.reactions.splice(Number(button.dataset.removeReaction),1);else{const from=Number(button.dataset.moveReaction),to=from+Number(button.dataset.reactionDirection);if(to>=0&&to<state.reactions.length)[state.reactions[from],state.reactions[to]]=[state.reactions[to],state.reactions[from]]}renderReactionProgram();persistSelectedDeck()},true);
const confirmReactionDeck=$('confirm-deck').onclick;$('confirm-deck').onclick=()=>{const selected=$('saved-decks').value;if(selected){const saved=loadSavedDecks().find(deck=>savedDeckKey(deck.owner_name,deck.name)===selected);state.reactions=[...(saved?.reactions||[])]}else state.reactions=[];confirmReactionDeck()};
exportDeckCode=function(){const ids=state.pool.map(card=>card.card_id),index=new Map(ids.map((id,i)=>[id,i])),bytes=ids.map(id=>state.deck[id]||0),conditions={if_able:0,card_in_hand:1,own_victory_points_at_most:2,opponent_victory_points_at_most:3,opponent_sync_at_most:4,opponent_victory_points_at_least:5,card_is:6,quantity_compare:7},quantities={cards_in_your_deck:0,cards_in_your_hand:1,cards_in_opponent_hand:2,your_flux:3,opponent_flux:4,your_sync:5,opponent_sync:6},comparisons={'<':0,'<=':1,'=':2,'>=':3,'>':4};bytes.push(state.rules.length);for(const rule of state.rules){const condition=conditions[rule.condition_type],action={play_named_card:0,play_random_card:1,end_turn:2}[rule.action_type];if(condition===undefined||action===undefined)throw Error('This deck has an unsupported rule.');bytes.push((condition<<4)|action);if(condition===1)bytes.push(index.get(rule.condition_card_id));else if(condition===6)bytes.push(index.get(rule.condition_card_id),rule.card_condition==='on_your_side_of_board'?1:0);else if(condition===7){const threshold=Number(rule.quantity_threshold);if(!Number.isInteger(threshold)||threshold<0||threshold>65535)throw Error('Quantity conditions must use a whole number from 0 through 65,535.');bytes.push(quantities[rule.quantity],comparisons[rule.comparison_operator],threshold>>8,threshold&255)}else if(condition!==0)bytes.push(rule.victory_points_threshold??rule.energy_threshold);if(action===0)bytes.push(index.get(rule.action_card_id));}bytes.push(state.reactions.length);for(const rule of state.reactions){const threshold=Number(rule.quantity_threshold);bytes.push(0,comparisons[rule.comparison_operator],threshold>>8,threshold&255,index.get(rule.action_card_id));}const mask=eligibleRandomCards().reduce((total,id)=>total|(1<<index.get(id)),0);bytes.push(state.defaultAction==='end_turn'?1:0,mask>>8,mask&255);return 'CD5.'+(state.formatId||'inaugural')+'.'+btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')};
const cd5ExportDeckCode=exportDeckCode;exportDeckCode=function(){if(state.pool.some(card=>card.card_kind==='glitch'))return cd5ExportDeckCode();const ids=state.pool.map(card=>card.card_id),index=new Map(ids.map((id,i)=>[id,i])),bytes=ids.map(id=>state.deck[id]||0),conditions={if_able:0,card_in_hand:1,own_victory_points_at_most:2,opponent_victory_points_at_most:3,opponent_sync_at_most:4,opponent_victory_points_at_least:5};bytes.push(state.rules.length);for(const rule of state.rules){const condition=conditions[rule.condition_type],action={play_named_card:0,play_random_card:1,end_turn:2}[rule.action_type];if(condition===undefined||action===undefined)throw Error('This rule belongs to a newer format.');bytes.push((condition<<4)|action);if(condition===1)bytes.push(index.get(rule.condition_card_id));else if(condition!==0)bytes.push(rule.victory_points_threshold??rule.energy_threshold);if(action===0)bytes.push(index.get(rule.action_card_id));}bytes.push(state.defaultAction==='end_turn'?1:0,eligibleRandomCards().reduce((mask,id)=>mask|(1<<index.get(id)),0));return 'CD4.'+(state.formatId||'inaugural')+'.'+btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')};
const narrativeWithReactions=richBattleLine;richBattleLine=function(event,player){const[who,detail='']=event.split(' | '),label=esc(player(who));if(detail.startsWith('reaction_play:')){const[,trigger,cardId,recipient]=detail.split(':'),response=trigger==='opponent_would_gain_flux'?esc(player(recipient))+' gaining Flux':'the triggering event';return label+' plays '+logCardReference(cardId)+' in response to '+response+'.'}return narrativeWithReactions(event,player)};

/* Action is the default program view; Reaction has no fallback action. */
function setProgramTab(tab){const reactionAvailable=!$('program-tab-reaction').hidden,selected=tab==='reaction'&&reactionAvailable?'reaction':'action';document.querySelectorAll('[data-program-tab]').forEach(button=>{const active=button.dataset.programTab===selected;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});$('action-program-panel').hidden=selected!=='action';$('reaction-program').hidden=selected!=='reaction'||!reactionAvailable}
document.addEventListener('click',event=>{const tab=event.target.closest('[data-program-tab]');if(tab)setProgramTab(tab.dataset.programTab)},true);
setProgramTab('action');

/* Render typed engine events through one card-agnostic narration library. */
let battleNarration=null;
const narrationAssetBase=(new URL(document.currentScript?.src||location.href,location.href)).pathname.replace(/\/[^/]*$/,'/');
const narrationReady=import(narrationAssetBase+'engine/narration.js').then(module=>{battleNarration=module;}).catch(()=>{});
const previousRichBattleLine=richBattleLine;
richBattleLine=function(event,player){if(battleNarration)return battleNarration.narrateBattleEvent(event,{player,card:logCardReference});return previousRichBattleLine(event,player)};
const previousBattleTurns=battleTurns;
battleTurns=function(log){if(!battleNarration)return previousBattleTurns(log);return battleNarration.groupBattleLogByTurn(log).map(events=>events.map(event=>richBattleLine(event,playerLabel)).filter(Boolean)).filter(turn=>turn.length)};
const previousTournamentTurns=tournamentTurns;
tournamentTurns=function(log,first,second){if(!battleNarration)return previousTournamentTurns(log,first,second);return battleNarration.groupBattleLogByTurn(log).map(events=>events.map(event=>richBattleLine(event,id=>id==='first'?first:second)).filter(Boolean)).filter(turn=>turn.length)};
if(typeof runScenario==='function'){const previousRunScenario=runScenario;runScenario=async function(id){await narrationReady;const item=state.scenarioItems.find(candidate=>candidate.scenario_id===id);if(!item)return;state.scenarioActive=item;state.logBattleNumber=1;worker().postMessage({type:'replay',submission:item.first,opponent:item.second,seed:item.seed,gameNumber:1,startingPlayer:item.starting_player,actionLimit:100000,config:item.config})}}

/* Flux and Sync conditions share the Reaction comparison controls. */
const comparisonConditionQuantities={own_victory_points_at_most:'your_flux',opponent_victory_points_at_most:'opponent_flux',opponent_victory_points_at_least:'opponent_flux',opponent_sync_at_most:'opponent_sync'};
function comparisonQuantityForType(type){return comparisonConditionQuantities[type]||(type==='quantity_compare'?$('condition-quantity').value:undefined)}
function renderComparisonRuleSentence(){const type=$('condition-type').value,quantity=comparisonQuantityForType(type),action=$('action-type').value,actionCard=$('action-card').value;if(quantity){$('rule-sentence').textContent='If '+quantityLabels[quantity]+' is '+comparisonLabels[$('comparison-operator').value]+' '+(type==='quantity_compare'?$('quantity-threshold').value:$('quantity-threshold').value)+', '+actionText(action,actionCard)+'.'}else $('rule-sentence').textContent=ruleText(type,$('condition-energy').value,$('condition-card').value,action,actionCard,$('card-condition').value)}
function renderComparisonConditionParameters(){const type=$('condition-type').value,isQuantity=type==='quantity_compare',isComparison=Boolean(comparisonQuantityForType(type));$('quantity-wrap').hidden=!isQuantity;$('comparison-wrap').hidden=!isComparison;$('quantity-threshold-wrap').hidden=!isComparison;$('condition-card-wrap').hidden=type!=='card_is';$('card-condition-wrap').hidden=type!=='card_is';$('condition-energy-wrap').hidden=true;renderComparisonRuleSentence()}
$('condition-type').onchange=renderComparisonConditionParameters;$('condition-card').onchange=renderComparisonRuleSentence;$('card-condition').onchange=renderComparisonRuleSentence;$('condition-energy').onchange=renderComparisonRuleSentence;$('condition-quantity').onchange=renderComparisonRuleSentence;$('comparison-operator').onchange=renderComparisonRuleSentence;$('quantity-threshold').oninput=renderComparisonRuleSentence;$('action-type').onchange=()=>{renderRuleSelectors();renderComparisonRuleSentence()};$('action-card').onchange=renderComparisonRuleSentence;
$('add-rule').onclick=()=>{const ids=deckIds(),selectedType=$('condition-type').value,action=$('action-type').value;if(!ids.length)return;if(state.rules.length>=10){$('status').textContent='A program can have at most 10 rules.';return}const rule={condition_type:selectedType,action_type:action},quantity=comparisonQuantityForType(selectedType);if(selectedType==='card_is'){rule.condition_card_id=$('condition-card').value;rule.card_condition=$('card-condition').value}else if(quantity){const threshold=Number($('quantity-threshold').value);if(!Number.isSafeInteger(threshold)||threshold<0){$('status').textContent='Quantity conditions need a whole number of 0 or more.';return}rule.condition_type='quantity_compare';rule.quantity=quantity;rule.comparison_operator=$('comparison-operator').value;rule.quantity_threshold=threshold}else if(selectedType!=='if_able')rule.energy_threshold=+$('condition-energy').value;if(action==='play_named_card')rule.action_card_id=$('action-card').value;state.rules.push(rule);state.selectedRule=state.rules.length-1;renderRules()};
const conditionSelect=$('condition-type'),conditionSelectWrap=conditionSelect.parentElement;conditionSelectWrap.id='condition-select-wrap';$('condition-builder').append(conditionSelectWrap);for(const legacyType of ['own_victory_points_at_most','opponent_victory_points_at_most','opponent_victory_points_at_least','opponent_sync_at_most'])conditionSelect.querySelector('option[value="'+legacyType+'"]')?.remove();renderComparisonConditionParameters();
function programRuleSentence(rule){const condition=rule.condition_type==='quantity_compare'?quantityConditionText(rule):conditionText(rule.condition_type,rule.victory_points_threshold??rule.energy_threshold,rule.condition_card_id,rule.card_condition),action=actionText(rule.action_type,rule.action_card_id);return rule.condition_type==='if_able'?'If able, '+action+'.':'If '+condition+', '+action+'.'}
renderRules=function(){const list=$('rules');list.innerHTML=state.rules.map((r,i)=>{const missing=unavailableRuleCards(r),warning=missing.length?'<small class="rule-warning">References '+esc(missing.map(name).join(' and '))+' outside this deck; this rule will be skipped.</small>':'';return '<li data-rule="'+i+'" draggable="true" class="'+(i===state.selectedRule?'selected ':'')+(missing.length?'rule-unavailable':'')+'"><span class="rule-priority">'+(i+1)+'</span><span class="rule-copy"><strong>'+esc(programRuleSentence(r))+'</strong><small>'+(i===0?'Highest priority rule.':'Runs after the rules above.')+'</small>'+warning+'</span><button class="delete-rule" type="button" aria-label="Delete rule '+(i+1)+'" onclick="removeRuleFromProgram('+i+')">×</button></li>'}).join('')||'<li class="empty-state">No rules yet. Your default action will be used.</li>';renderDeckPreview();renderDefaultAction();persistSelectedDeck()};
